/// Returns an error for a negative base revision or a node that is not running.
Future<void> publishShareSnapshot({
  required String peerId,
  required PlatformInt64 baseRevision,
  required ShareManifest manifest,
}) => RustLib.instance.api.crateApiPublishShareSnapshot(
  peerId: peerId,
  baseRevision: baseRevision,
  manifest: manifest,
);

/// Input for [`bind_share`]. Grouping the optional native path keeps the FRB
/// signature stable while letting the wrapper consume every owned argument.
class BindShareParams {
  /// Share to bind.
  final String shareId;

  /// Real local directory, or `None` to clear the binding.
  final String? localRoot;

  const BindShareParams({required this.shareId, this.localRoot});

  @override
  int get hashCode => shareId.hashCode ^ localRoot.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is BindShareParams &&
          runtimeType == other.runtimeType &&
          shareId == other.shareId &&
          localRoot == other.localRoot;
}

/// Input for [`create_share`]. Grouping the optional native path keeps the FRB
/// signature stable while letting the wrapper consume every owned argument.
class CreateShareParams {
  /// Human-readable share name.
  final String name;

  /// `private` or `public`.
  final String kind;

  /// Whether a public share accepts writes.
  final bool publicWrite;

  /// Real local directory bound to this share, if any.
  final String? localRoot;

  const CreateShareParams({
    required this.name,
    required this.kind,
    required this.publicWrite,
    this.localRoot,
  });

  @override
  int get hashCode =>
      name.hashCode ^ kind.hashCode ^ publicWrite.hashCode ^ localRoot.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is CreateShareParams &&
          runtimeType == other.runtimeType &&
          name == other.name &&
          kind == other.kind &&
          publicWrite == other.publicWrite &&
          localRoot == other.localRoot;
}

/// One share as both frontends see it. The domain type is deliberately not
/// serializable, so this DTO keeps the FRB and web JSON shapes identical.
class MobileShare {
  /// Stable id shared with peers on the wire.
  final String shareId;

  /// Verified id of the owning account.
  final String ownerUserId;

  /// Human-readable share name.
  final String name;

  /// `private` or `public`.
  final String kind;

  /// Whether a public share accepts writes.
  final bool publicWrite;

  /// Real local directory bound to this share, if any.
  final String? localRoot;

  /// Current manifest revision.
  final PlatformInt64 revision;

  const MobileShare({
    required this.shareId,
    required this.ownerUserId,
    required this.name,
    required this.kind,
    required this.publicWrite,
    this.localRoot,
    required this.revision,
  });

  @override
  int get hashCode =>
      shareId.hashCode ^
      ownerUserId.hashCode ^
      name.hashCode ^
      kind.hashCode ^
      publicWrite.hashCode ^
      localRoot.hashCode ^
      revision.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is MobileShare &&
          runtimeType == other.runtimeType &&
          shareId == other.shareId &&
          ownerUserId == other.ownerUserId &&
          name == other.name &&
          kind == other.kind &&
          publicWrite == other.publicWrite &&
          localRoot == other.localRoot &&
          revision == other.revision;
}

/// One target user's permission on a share.
class MobileShareGrant {
  /// Verified target user id.
  final String userId;

  /// `readonly` or `readwrite`.
  final String mode;

  const MobileShareGrant({required this.userId, required this.mode});

  @override
  int get hashCode => userId.hashCode ^ mode.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is MobileShareGrant &&
          runtimeType == other.runtimeType &&
          userId == other.userId &&
          mode == other.mode;
}

/// Fields for persisting one incoming broadcast or DM.
///
/// FRB 2.13 emits one Dart named argument per Rust parameter, so grouping the
/// values into a struct keeps both this signature and the generated Dart call
/// small. The web transport keeps its flat JSON shape; only the FRB adapter
/// builds this struct.
class SaveIncomingMessageParams {
  /// Message body (may be empty for an attachment-only message).
  final String content;

  /// Sender peer id.
  final String peerId;

  /// `true` for a DM, `false` for a broadcast.
  final bool isDirect;

  /// Announced sender nickname, if any.
  final String? nickname;

  /// Live round-trip decoration (never persisted).
  final String? latency;

  /// Stable wire message id (reply/receipt correlation).
  final String? msgId;

  /// Immutable reply snapshot (US-006).
  final ReplyRef? replyTo;

  /// Rust-built file descriptor from the live event (files lane §12).
  final MobileAttachment? attachment;

  /// Whether the DM arrived sealed end to end (US-042).
  final bool encrypted;

  const SaveIncomingMessageParams({
    required this.content,
    required this.peerId,
    required this.isDirect,
    this.nickname,
    this.latency,
    this.msgId,
    this.replyTo,
    this.attachment,
    required this.encrypted,
  });

  @override
  int get hashCode =>
      content.hashCode ^
      peerId.hashCode ^
      isDirect.hashCode ^
      nickname.hashCode ^
      latency.hashCode ^
      msgId.hashCode ^
      replyTo.hashCode ^
      attachment.hashCode ^
      encrypted.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is SaveIncomingMessageParams &&
          runtimeType == other.runtimeType &&
          content == other.content &&
          peerId == other.peerId &&
          isDirect == other.isDirect &&
          nickname == other.nickname &&
          latency == other.latency &&
          msgId == other.msgId &&
          replyTo == other.replyTo &&
          attachment == other.attachment &&
          encrypted == other.encrypted;
}
